    <a class="skip-link" href="#main">Skip to main content</a>
    <div class="page-shell">
      <header>
        <a class="brand" href="#" aria-label="Purrfect Guide home">
          <span class="brand-mark" aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
              <path d="M4.5 10.2 6 4.8l4 2.5a9.2 9.2 0 0 1 4 0l4-2.5 1.5 5.4c.6 4.8-2.8 8.8-7.5 8.8s-8.1-4-7.5-8.8Z"></path>
              <path d="M8.5 13.3h.01M15.5 13.3h.01M10 16c1.1.8 2.9.8 4 0"></path>
            </svg>
          </span>
          <span>Purrfect Guide</span>
        </a>
      </header>

      <main id="main" tabindex="-1">
        <section class="hero" aria-labelledby="page-title">
          <div>
            <p class="eyebrow">Cat care, made simple</p>
            <h1 id="page-title">Cat FAQ</h1>
            <p class="hero-copy">
              Quick answers for new and experienced cat guardians, from feeding and play to grooming,
              enrichment, and everyday health signals.
            </p>
          </div>
          <aside class="hero-card" aria-label="Cat care note">
            <img
              alt="Orange tabby cat resting comfortably on a soft blanket"
              src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 800'%3E%3Crect width='800' height='800' fill='%23eadfd1'/%3E%3Ccircle cx='400' cy='430' r='220' fill='%23c96f3d'/%3E%3Cpath d='M240 310 285 155l115 92 115-92 45 155' fill='%23b85d31'/%3E%3Ccircle cx='325' cy='420' r='20' fill='%2317120f'/%3E%3Ccircle cx='475' cy='420' r='20' fill='%2317120f'/%3E%3Cpath d='M370 485c20 25 40 25 60 0' fill='none' stroke='%2317120f' stroke-width='20' stroke-linecap='round'/%3E%3Cpath d='M400 462v35' stroke='%2317120f' stroke-width='16' stroke-linecap='round'/%3E%3Cpath d='M180 520h145M475 520h145M195 585h130M475 585h130' stroke='%235d220f' stroke-width='12' stroke-linecap='round'/%3E%3C/svg%3E">
            <p>Tip: if your cat's behavior changes suddenly, contact a veterinarian for guidance.</p>
          </aside>
        </section>

        <section class="faq-panel" aria-labelledby="faq-title">
          <h2 class="faq-heading" id="faq-title">Frequently asked questions</h2>
          <div id="faq-root"></div>
        </section>
      </main>

      <footer>
        <p>General information only. Always follow your veterinarian's advice for your cat's specific needs.</p>
      </footer>
    </div>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with measured meals two or more times a day, while kittens usually need more frequent feeding. Use your cat food label and your veterinarian's guidance to match portions to age, size, activity, and health needs."
        },
        {
          question: "Why does my cat knead with their paws?",
          answer:
            "Kneading is a normal comfort behavior that begins in kittenhood. Many cats knead when they feel safe, relaxed, or ready to settle in for a nap."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from daily play, scratching posts, climbing spaces, window views, scent exploration, and puzzle feeders. Enrichment helps support exercise and reduces boredom-related behavior."
        },
        {
          question: "How can I tell if my cat is stressed?",
          answer:
            "Signs can include hiding, appetite changes, over-grooming, aggression, litter box changes, or unusual vocalizing. If signs persist or appear suddenly, schedule a veterinary check."
        },
        {
          question: "Should cats drink milk?",
          answer:
            "Most cats do not need milk, and many adult cats cannot digest lactose well. Fresh water should be available every day; ask your veterinarian about safe treats for your individual cat."
        },
        {
          question: "How often should I clean the litter box?",
          answer:
            "Scoop at least once daily and refresh the litter regularly. A clean, quiet, accessible box encourages good litter habits and helps you notice changes in urination or stool."
        }
      ];

      function createFaqItem(item, index) {
        const itemId = `faq-answer-${index + 1}`;
        const wrapper = document.createElement("div");
        wrapper.className = "example";

        wrapper.innerHTML = `
          <h3>
            <button class="question-button" type="button" aria-expanded="false" aria-controls="${itemId}">
              <span>${item.question}</span>
              <span class="icon" aria-hidden="true">+</span>
            </button>
          </h3>
          <div class="details" id="${itemId}" hidden>
            <p>${item.answer}</p>
          </div>
        `;

        const button = wrapper.querySelector("button");
        const details = wrapper.querySelector(".details");

        button.addEventListener("click", () => {
          const isExpanded = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isExpanded));
          details.hidden = isExpanded;
        });

        return wrapper;
      }

      function FaqList(items) {
        const list = document.createElement("div");
        list.className = "faq-list";

        items.forEach((item, index) => {
          list.append(createFaqItem(item, index));
        });

        return list;
      }

      function App() {
        const root = document.getElementById("faq-root");
        root.append(FaqList(faqs));
      }

      App();
    </script>
  </body>
</html>
